(function(){
  'use strict';
  const D=GameData,E=GameEngine,KEY='time-poverty-prd1-v7-save',PREF='time-poverty-demo-prefs';
  const app=document.getElementById('app'),modal=document.getElementById('modal');
  let state=null,home=true,paid=false,busy=false,loadError='',rawBroken='',storageOK=true;
  let prefs={fast:true,motion:true};
  const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmt=x=>Number(x).toFixed(2).replace(/\.00$/,'').replace(/(\.\d)0$/,'$1');
  const clock=x=>`${String(Math.floor(x/60)).padStart(2,'0')}:${String(x%60).padStart(2,'0')}`;
  const category={normal:'普通体验',good:'正合心意',bad:'计划外状况'};
  const symbol={normal:'○',good:'✦',bad:'↯'};
  function load(){try{const raw=localStorage.getItem(KEY);if(raw)state=E.validate(JSON.parse(raw));const p=localStorage.getItem(PREF);if(p)prefs={...prefs,...JSON.parse(p)};}catch(err){loadError=err.message;try{rawBroken=localStorage.getItem(KEY)||'';}catch{storageOK=false;}}}
  function toast(s){const el=document.getElementById('notice');el.textContent=s;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3300);}
  function button(label,act,cls='primary',extra=''){return `<button class="${cls}" data-action="${act}" ${state?`data-token="${E.token(state)}"`:''} ${extra}>${label}</button>`;}
  function scene(name,label=''){return `<div class="scene scene-${name}"><img src="${D.assets[name]}" alt="${esc(label)}"><span class="scene-stamp">生活观察日记 / SEVEN DAYS</span></div>`;}
  function header(){const totals=state?E.totals(state):null;return `<header class="topbar"><button class="brand" data-action="home" aria-label="返回标题页"><span class="brand-icon">◷</span><span>给自己一点时间<small>A LITTLE TIME FOR YOURSELF</small></span></button><nav aria-label="游戏菜单">${state&&!home?`<span class="save-indicator"><i></i> 已自动保存</span>`:''}<button class="text-button" data-action="rules">玩法说明</button>${state?'<button class="text-button" data-action="ledger">记录</button>':''}<button class="icon-button" data-action="settings" aria-label="设置">⚙</button></nav></header>${totals&&!home?`<div class="resourcebar"><div class="day-badge">DAY <strong>${String(state.day).padStart(2,'0')}</strong><span>/ 07</span></div><div><small>当前钱包</small><strong>¥ ${state.cash}</strong></div><div><small>已结算幸福总分</small><strong>${fmt(totals.sum/6)} <em>/ 565</em></strong></div><div><small>已达标天数</small><strong>${totals.good} <em>/ 6 天</em></strong></div><div class="week-dots">${Array.from({length:7},(_,i)=>`<span class="${state.days[i]?(state.days[i].score>=360?'done':'low'):i===state.day-1?'active':''}" title="第${i+1}天${state.days[i]?`：${fmt(state.days[i].score/6)}分`:''}">${i+1}</span>`).join('')}</div></div>`:''}`;}
  function title(){return `<main class="landing"><section class="landing-copy"><span class="eyebrow">七日生活决策游戏 · DEMO</span><h1>今天，有多少时间<br>是<span>属于你的？</span></h1><p class="lead">工作要做，生活要过。<br>用有限的钱和一点好运，找回被日程挤走的自己。</p><div class="landing-goals"><div><b>07</b><span>个工作日</span></div><div><b>¥ 55</b><span>初始钱包</span></div><div><b>565</b><span>周幸福目标</span></div></div><div class="hero-actions">${state&&!loadError?button(`继续第 ${state.day} 天 →`,'continue'):''}${button(state?'重新开始':'开始我的七天 →',state?'restart':'new',state?'secondary':'primary')}</div>${loadError?`<p class="error">存档暂时无法读取：${esc(loadError)}。新开一局前可先导出旧存档。</p>${button('导出旧存档','export-broken','secondary')}`:''}<p class="footnote">单人 · 可随时退出 · 自动保存进度<br>七个工作日关卡，不代表连续七天上班。</p></section><section class="hero-art">${scene('leisure','夜晚的小房间，沙发、台灯与打开的速写本')}<div class="floating-note"><span>给今天的自己</span><b>休息，也算正事。</b><p>不是每一分钟，都要交给待办清单。</p></div></section></main><footer>时间贫困 · PRD 1.0 / 第七版 · 概率调整版 <span>局内金额不涉及真实消费</span></footer>`;}
  function timeline(){const rows=D.schedules[state.day-1];return `<aside class="timeline panel"><div class="section-label">今日时间轴 <span>基准日程</span></div><div class="timeline-list">${rows.map((r,i)=>{const done=i<state.index||['day','week'].includes(state.phase),active=i===state.index&&state.phase==='play';const rec=state.events.find(e=>e.key===r.key);let hint=r.choice?'0 / 50 元 · 全天一次':r.am||r.id==='work'?(state.pending?`${state.pending.paid?'已购全天协助':'全天自己完成'} · ${r.am?'已锁定':'待结算'}`:r.id==='work'&&done?'全天结果已结算':'沿用全天方案'):r.id?`0 / ${D.byId[r.type].cost} 元`:r.pay?'净入账 35 元':r.base?'自由安排':'固定日程';if(rec&&rec.delta!==undefined&&!rec.locked)hint=`${rec.delta>=0?'省':'延误'} ${Math.abs(rec.delta)} 分钟${rec.spare?` · 可用${rec.spare}分钟`:''}`;return `<div class="timeline-row ${done?'done':''} ${active?'current':''}"><span class="timeline-dot">${done?'✓':''}</span><time>${clock(r.start)}</time><div><b>${esc(r.label)}</b><small>${esc(hint)}</small>${active&&state.delay?`<small class="delay">实际 ${clock(r.start+state.delay)} 开始</small>`:''}</div></div>`;}).join('')}<div class="timeline-row bedtime"><span class="timeline-dot">☾</span><time>22:00</time><div><b>睡觉</b><small>留给明早一整晚休息</small></div></div></div></aside>`;}
  function overview(){const theme=D.themes[state.day-1];return `<main class="overview-grid"><section class="overview-main"><span class="eyebrow">DAY ${String(state.day).padStart(2,'0')} / 一天的开始</span><h1>${theme[0]}</h1><p class="lead">${theme[1]}</p>${scene(state.day===1?'commute':state.day>=5?'home':'kitchen','今日生活场景')}<div class="overview-bottom"><div><b>今天的新变化</b><p>${theme[2]}</p>${state.day===4&&state.effects.some(e=>e.type==='prep')?'<p class="positive">✦ 昨天备好了菜：今晚额外省5分钟。</p>':''}${state.day===6&&state.delay?'<p class="delay">↯ 台灯复查已占用5分钟，今天从07:05开始。</p>':''}</div>${button('开始今天 →','begin')}</div></section>${timeline()}</main>`;}
  function outcomes(type,paid){const t=D.byId[type];return `<div class="odds"><div><i class="normal">○</i><b>普通 <small>35%</small></b><span>省 ${paid?t.paidNormal:'1–2'} 分钟</span></div><div><i class="good">✦</i><b>正合心意 <small>38.5%</small></b><span>省 ${paid?t.paidGood:t.freeGood} 分钟</span></div><div><i class="bad">↯</i><b>计划外 <small>26.5%</small></b><span>延误 ${paid?t.paidBad:t.freeBad} 分钟</span></div></div>`;}
  function choiceView(r){const t=D.byId[r.choice||r.type],notEnough=state.cash<t.cost;if(paid&&notEnough)paid=false;return `<div class="section-label">怎么安排这一件事？</div><div class="choices"><button class="choice ${!paid?'selected':''}" data-action="free"><span class="radio"></span><span><b>${t.free}</b><small>基础开销已包含在生活费中</small></span><strong>+ ¥ 0</strong></button><button class="choice ${paid?'selected':''}" data-action="paid" ${notEnough?'disabled':''}><span class="radio"></span><span><b>${t.paid}</b><small>${notEnough?`还差 ${t.cost-state.cash} 元，工资不能提前使用`:'购买服务，也要接受不确定性'}</small></span><strong>+ ¥ ${t.cost}</strong></button></div>${outcomes(t.id,paid)}<p class="fineprint">普通空档体验 ×1；正合心意 ×1.2。先追回延误，剩余才是自主时间。</p>${r.choice?'<p class="work-note">这笔选择覆盖上午和下午共8小时工作，只付一次、抽一次，下午统一结算。</p>':''}<div class="confirm-line"><span>确认后余额 <b>¥ ${state.cash-(paid?t.cost:0)}</b></span>${button(paid?`支付 ¥${t.cost}，抽取结果 →`:'确认免费方案，抽取结果 →','choose')}</div>`;}
  function drawView(r){return `<div class="draw-view"><span class="eyebrow">方案已确认 · 结果已保存</span><h2>生活会给你哪一张牌？</h2><p>${state.current.paid?`已额外支出 ¥${state.current.cost}。`:'没有额外支出。'}翻开一张，看看今天的小意外。</p><div class="card-backs">${[1,2,3].map(n=>`<button class="card-back" data-action="reveal" data-token="${E.token(state)}" aria-label="翻开第${n}张结果卡"><span>◷</span><small>生活的另一面</small></button>`).join('')}</div><p class="fineprint">普通35% · 正合心意38.5% · 计划外26.5%<br>选择任意位置揭示同一个已抽取结果，刷新不会重新抽卡。</p></div>`;}
  function resultView(r,e,locked=false){const tmp=JSON.parse(JSON.stringify(state)),p=E.applyTime(tmp,e),t=D.byId[e.type],idx=(e.paid?3:0)+(['normal','good','bad'].indexOf(e.kind));const story=D.stories[e.type][idx];return `<div class="result-card ${e.kind}"><div class="result-top"><span>${symbol[e.kind]} ${category[e.kind]}</span><b>${e.delta>=0?'省下':'延误'} ${Math.abs(e.delta)} <small>分钟</small></b></div><h2>${esc(story)}</h2>${locked?'<p>全天工作卡已锁定。先完成上午工作，下午再结算这里的省时或延误。</p>':`<div class="result-math"><span>追回进度 <b>${p.caught} 分钟</b></span><span>真正可用 <b>${p.spare} 分钟</b></span><span>体验分钟 <b>${fmt(p.added/5)}</b></span></div><p>${e.kind==='bad'?`后续日程将顺延；当前待追回延误 ${p.delayAfter} 分钟。`:p.spare>0?(e.kind==='good'?`这段空档正好可以${D.needs[e.type]}，按1.2体验计算。`:'这段空档可以自主安排，按正常体验计算。'):'省下的时间全部用于追回进度，这次没有产生休息空档。'}</p>`}${state.day===3&&e.type==='grocery'&&e.kind==='good'?'<p class="chain">↳ 明日晚饭额外省5分钟，按普通体验结算。</p>':''}${state.day===5&&e.type==='repair'&&e.kind==='bad'?'<p class="chain">↳ 明早需要复查台灯，额外占用5分钟；只发生一次。</p>':''}${state.day===4&&e.type==='dinner'&&state.effects.some(x=>x.type==='prep'&&!x.used)?'<p class="chain">↳ 还有昨日备菜：随后额外省5分钟，优先追回延误。</p>':''}</div><div class="result-footer"><small>${e.paid?`额外支出 ¥${e.cost} · 当前余额 ¥${state.cash}`:'额外支出 ¥0'}${locked?' · 幸福值尚未计入':''}</small>${button(locked?'记下结果，开始工作 →':'接受结果，继续今天 →','advance')}</div>`;}
  function fixedView(r){if(r.id==='work')return `<p class="work-note">沿用上午选择：${state.pending.paid?'全天工作协助':'全天自己完成'}。这里仅结算一次，不再付款、不再抽卡。</p>${resultView(r,state.pending)}`;if(r.pay)return `<div class="payday"><span>今天的工作完成了</span><h2>工资到账 <b>+ ¥35</b></h2><div><p>日结工资 <strong>+ ¥150</strong></p><p>基础生活费 <strong>− ¥115</strong></p></div><small>住房水电60 · 餐食40 · 往返公交8 · 基本消耗7</small><p>实际到账时间 ${clock(1080+state.delay)}，确认后钱包 ¥${state.cash+35}。</p></div>${button('收好工资，准备回家 →','advance')}`;if(r.base){const night=E.base(state.day)-state.delay;return `<div class="rest-view"><span class="eyebrow">今天剩下的时间，交还给你</span><h2>${night}<small>分钟</small></h2><p>听歌、随手画画，或者什么也不做。<br>这里无需再花钱，也没有“选错”的休息。</p><div class="rest-tags"><span>♫ 听一会歌</span><span>✎ 画一点画</span><span>☾ 安心发呆</span></div><small>今晚普通体验 ${night} 分钟；白天已享受 ${state.real} 分钟空档。</small></div>${button('享受这段时间，结束今天 →','advance')}`;}return `<div class="fixed-view"><span class="eyebrow">生活按自己的节奏继续</span><h2>${r.label}</h2><p>${r.am?`沿用早上${state.pending?.paid?'购买的全天协助':'自己完成的全天方案'}，工作结果已经锁定。`:'这段是固定生活安排，不额外收费，也不会随机改变时长。'}</p><b>${r.duration} 分钟</b><p class="fineprint">${r.label==='必要午间休息'?'必要休息不重复计入自主时间。':'当前延误会顺延后续安排，不会扣掉已经享受过的空档。'}</p></div>${button('完成，继续下一项 →','advance')}`;}
  function play(){const r=E.row(state);let content=state.stage==='draw'?drawView(r):state.stage==='result'?resultView(r,state.current,!!r.choice):(r.choice||(r.id&&r.id!=='work'))?choiceView(r):fixedView(r);return `<main class="play-grid">${timeline()}<section class="play-center"><div class="day-title"><div><span class="eyebrow">DAY ${String(state.day).padStart(2,'0')} · ${D.themes[state.day-1][0]}</span><h1>${r.label}</h1></div><div class="clock"><b>${clock(r.start+state.delay)}</b><small>${state.delay?`比基准晚 ${state.delay} 分钟`:'日程正常进行'}</small></div></div>${scene(r.scene,`${r.label}的生活场景`)}<div class="moment-stats"><span>已享受空档 <b>${state.real} 分钟</b></span><span>对应体验 <b>${fmt(state.units/5)} 分钟</b></span><span class="${state.delay?'delay':''}">待追回 <b>${state.delay} 分钟</b></span></div><section class="interaction panel" aria-live="polite">${content}</section><p class="play-note">日分在22:00锁定。真实分钟决定日程，体验分钟用于幸福评分。</p></section></main>`;}
  function breakdown(d){return `<details class="calculation"><summary>展开时间与幸福分计算</summary><p>白天空档：${d.gapReal} 个真实分钟 → ${fmt(d.gapUnits/5)} 个体验分钟</p><p>夜间自由：基准 ${d.base} − 剩余延误 ${d.delay} = ${d.night} 分钟</p><p>体验分钟合计：${fmt(d.gapUnits/5)} + ${d.night} = ${fmt(d.experience)}</p><p>幸福分：min(100, ${fmt(d.experience)} ÷ 120 × 100) = <b>${fmt(d.score/6)}</b></p><small>显示分数保留两位小数，通关按未四舍五入的分数判断。</small></details>`;}
  function dayReport(){const d=state.days.at(-1),totals=E.totals(state);return `<main class="report"><span class="eyebrow">DAY ${String(state.day).padStart(2,'0')} / 22:00 · 今日已收好</span><h1>${d.score>=360?'给自己留住了一点时间。':'今天有点挤，辛苦了。'}</h1><div class="report-layout"><section class="score-card"><span>今日幸福分</span><strong>${fmt(d.score/6)}</strong><b class="${d.score>=360?'positive':'delay'}">${d.score>=360?'✓ 达到60分':'尚未达到60分'}</b><p>这一天已经锁定，后面的花费不会改写它。</p></section><section class="report-details"><div class="metric-grid"><div><small>真实自主时间</small><b>${d.real}<em> 分钟</em></b></div><div><small>体验时间</small><b>${fmt(d.experience)}<em> 分钟</em></b></div><div><small>今日额外支出</small><b>¥ ${d.spent}</b></div><div><small>剩余钱包</small><b>¥ ${d.cash}</b></div></div>${breakdown(d)}</section></div>${totals.impossible?'<p class="warning">已有两天低于60分，本局无法达成“至少六天达标”。你仍可以完成七天，看看自己的生活记录。</p>':''}${state.effects.filter(e=>!e.used&&e.day===state.day+1).map(e=>`<p class="chain">明日提醒：${e.type==='prep'?'备好的食材让晚饭额外省5分钟。':'07:00复查台灯，占用5分钟。'}</p>`).join('')}<div class="report-actions">${button('查看今日账单','ledger','secondary')}${button(state.day===7?'查看七日回顾 →':'收好今天，进入下一天 →','next')}</div></main>`;}
  function weekReport(){const t=E.totals(state);return `<main class="report week-report"><span class="eyebrow">七日回顾 / A WEEK OF YOUR LIFE</span><h1>${t.won?'你给生活留出了自己的位置。':'七天结束，生活还可以重新安排。'}</h1><p class="lead">${t.won?'你既照顾了这一周，也没有忽略每天的自己。':'这次的取舍已经留下记录。带着一点新经验，再试一次。'}</p><div class="week-score"><div><span>七日幸福总分</span><strong>${fmt(t.sum/6)}<small> / 565</small></strong></div><div><span>达到60分的天数</span><strong>${t.good}<small> / 6 天</small></strong></div><div><span>本局结果</span><strong class="${t.won?'positive':'delay'}">${t.won?'挑战成功':'未达成'}</strong></div></div><div class="score-chart" aria-label="七天幸福分">${state.days.map(d=>`<div><b>${fmt(d.score/6)}</b><div class="bar-track"><span style="height:${d.score/6}%" class="${d.score>=360?'':'low'}"></span><i></i></div><small>第 ${d.day} 天</small></div>`).join('')}</div><p>${t.sum<3390?`周总分距离目标还差 ${fmt((3390-t.sum)/6)} 分。`: '✓ 周幸福总分达标。'} ${t.good<6?`只有 ${t.good} 天达到60分，需要至少6天。`:'✓ 至少六天幸福分达标。'}</p><p class="fineprint">七天共额外花费 ¥${state.spent}，余额 ¥${state.cash}。余钱不兑换幸福分，单日超出100的部分不结转。</p><div class="report-actions">${button('导出本局试玩记录','export','secondary')}${button('再过一次这七天 →','restart')}</div></main>`;}
  const lowDayPrompts=new Set();
  function promptSecondLowDay(){
    if(home||!state||state.phase!=='day'||modal.open)return;
    const lows=state.days.filter(d=>d.score<360);
    const key=state.id+':'+state.day;
    if(lows.length!==2||lows[1].day!==state.day||lowDayPrompts.has(key))return;
    lowDayPrompts.add(key);
    dialog('再来一局，重新安排生活',`<p>第 ${lows[0].day} 天和第 ${lows[1].day} 天的幸福值低于60分。</p><p>通关需要至少六天达到60分，出现第二个低分日后，本局已无法通关。试着重新安排下一局吧。</p><p class="fineprint">新开一局会覆盖当前进度，你可以先导出本局记录。</p><div class="modal-actions">${button('重新开始一局','confirm-new')}${button('导出本局记录','export','secondary')}${button('先查看本局结算','close','text-button')}</div>`);
  }
  function render(){document.body.classList.toggle('reduce-motion',!prefs.motion);app.innerHTML=header()+(home?title():state.phase==='overview'?overview():state.phase==='play'?play():state.phase==='day'?dayReport():weekReport());const current=app.querySelector('.timeline-row.current');if(current){const list=app.querySelector('.timeline-list');list.scrollTop=Math.max(0,current.offsetTop-list.offsetTop-120);}promptSecondLowDay();}
  function save(next){try{localStorage.setItem(KEY,JSON.stringify(next));state=next;loadError='';}catch(err){throw Error('浏览器未能保存进度。请允许本地存储或检查磁盘空间；本次操作没有生效。');}}
  function skipFixed(s){if(!prefs.fast)return s;let r=E.row(s);while(s.phase==='play'&&!r.id&&!r.choice&&!r.pay&&!r.base){s=E.reduce(s,{type:'advance',token:E.token(s)});r=E.row(s);}return s;}
  async function act(type,tok){if(busy)return;busy=true;try{const commit=()=>{const raw=localStorage.getItem(KEY);if(raw){const latest=E.validate(JSON.parse(raw));if(state&&latest.id!==state.id){state=latest;paid=false;render();throw Error('另一个窗口已开始新一局，请在当前进度继续。');}state=latest;}let next=E.reduce(state,{type,paid,token:tok});if(next===state)return;next=skipFixed(next);save(next);paid=false;render();};if(navigator.locks)await navigator.locks.request(KEY,commit);else commit();}catch(err){toast(err.message);}finally{busy=false;}}
  function dialog(title,body){modal.innerHTML=`<div class="modal-header"><h2>${title}</h2><button class="icon-button" data-action="close" aria-label="关闭弹窗">✕</button></div>${body}`;modal.showModal();}
  function newGame(){try{const seed=new Uint32Array(1);crypto.getRandomValues(seed);save(E.create(seed[0]));home=false;paid=false;modal.close();render();}catch(err){toast(err.message);}}
  function download(raw,name){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([raw],{type:'application/json;charset=utf-8'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function ledger(){const money=state.money.filter(x=>x.day===state.day);const events=state.events.filter(e=>e.day===state.day);dialog(`第 ${state.day} 天 · 生活账本`,`<div class="ledger"><h3>钱包收支</h3>${money.length?money.map(m=>`<p><span>${clock(m.time)} · ${esc(m.label)}</span><b>${m.amount>0?'+':'−'} ¥${Math.abs(m.amount)}<small>余额 ¥${m.balance}</small></b></p>`).join(''):'<p>今天还没有额外收支。</p>'}<h3>已发生的日程</h3>${events.map(e=>`<p><span>${clock(e.start)} · ${esc(e.label)}<small>${e.locked?'全天卡已锁定，下午结算':e.base?`晚间自由 ${e.real} 分钟`:e.resolved?`${category[e.kind]} · ${e.delta>=0?'省':'延误'}${Math.abs(e.delta)}分钟；追回${e.caught}，可用${e.spare}${e.bonus?`；备菜另追回${e.bonus.caught}，可用${e.bonus.spare}`:''}`:e.carry?'昨晚维修的后续影响':e.pay?'工资与基础开销合并净入账':'固定进行'}</small></span><b>${e.locked?'已锁定':e.pay?'已到账':'已完成'}</b></p>`).join('')||'<p>今天还没开始，日程正在等你。</p>'}</div>${button('导出完整记录','export','secondary')}`);}
  function rules(){dialog('把一点时间留给自己',`<div class="rules"><p>你有 <b>55元</b>开局资金，要度过七个工作日。每天下班领取150元工资，同时结清115元基础生活费，钱包<b>净增加35元</b>。</p><h3>每件事，做一次取舍</h3><p>免费和付费都可能遇到普通35%、正合心意38.5%、计划外26.5%。花钱买服务，不保证顺利。价格都是额外差价。</p><h3>省下的时间，先把延误补回来</h3><p>例如之前晚10分钟，现在省20分钟，只有剩下的10分钟能休息。普通体验×1，正合心意×1.2；10分钟好体验算12体验分钟，时钟仍只过10分钟。</p><h3>每天60分，是照顾自己的底线</h3><p>日幸福分＝体验分钟÷120×100，上限100。七天总分至少<b>565</b>，且至少<b>六天达到60分</b>，全部事项完成并且不透支才能通关。超出的日分不结转，已经结束的一天不能补分。</p><h3>一份工作，只做一次选择</h3><p>09:00选择全天自己做或额外50元购买协助。上午下午沿用同一方案，只抽一次结果；下午完成工作时统一结算，最早18:00领工资。</p><p class="fineprint">幸福分是游戏对自主时间的简化评分。进度仅保存在当前浏览器；清理浏览器数据会删除存档。桌面浏览器为本Demo主要试玩平台。</p></div>`);}
  document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;if(['begin','choose','reveal','advance','next'].includes(a)){act(a,b.dataset.token);return;}if(a==='new')newGame();if(a==='continue'){home=false;render();}if(a==='home'){home=true;render();}if(a==='free'||a==='paid'){paid=a==='paid';render();}if(a==='close')modal.close();if(a==='rules')rules();if(a==='ledger'&&state)ledger();if(a==='restart')dialog('重新开始七天？',`<p>这会覆盖当前进度。你可以先导出试玩记录，再开始新的一局。</p><div class="modal-actions">${state?button('先导出记录','export','secondary'):''}${button('确认重新开始','confirm-new')}${button('继续原来的生活','close','text-button')}</div>`);if(a==='confirm-new')newGame();if(a==='export'&&state)download(JSON.stringify({exportedAt:new Date().toISOString(),rules:'PRD1.0 第七版 概率调整版',totals:E.totals(state),state},null,2),`时间贫困-第${state.day}天-${state.id}.json`);if(a==='export-broken')download(rawBroken,'时间贫困-旧存档备份.json');if(a==='settings')dialog('按自己的节奏玩',`<label class="setting"><input id="fast" type="checkbox" ${prefs.fast?'checked':''}>自动推进固定生活片段<small>早餐、洗漱等固定安排仍完整执行；选择、工资和日结会停下来。</small></label><label class="setting"><input id="motion" type="checkbox" ${prefs.motion?'checked':''}>轻量场景动画<small>关闭不影响卡面、概率或任何分数。</small></label><p class="fineprint">数值基线：PRD 1.0 / 第七版 · 概率调整版。所有消费均为游戏内货币。</p>`);});
  modal.addEventListener('change',e=>{if(['fast','motion'].includes(e.target.id)){prefs[e.target.id]=e.target.checked;try{localStorage.setItem(PREF,JSON.stringify(prefs));}catch{}render();}});
  modal.addEventListener('click',e=>{if(e.target===modal)modal.close();});
  window.addEventListener('storage',e=>{if(e.key===KEY){try{state=e.newValue?E.validate(JSON.parse(e.newValue)):null;if(!state)home=true;paid=false;render();toast('已同步另一个窗口的进度。');}catch{toast('另一个窗口的存档无法读取，请重新打开。');}}});
  load();render();
})();
